mapper.select:
select l.live_id as id, l.biz_code as bizCode, l.course_id as courseId,
       l.topic_id as topicId, t.topic_name as topic, l.creator_id as creatorId,
       c.creator_name as teacher, c.avatar as teacherAvatar, l.title, l.subtitle,
       l.description, l.cover_image as coverImage, l.start_time as startTime,
       l.end_time as endTime, l.status as statusCode, l.h5_url as h5Url,
       l.replay_url as replayUrl, l.duration_seconds as durationSeconds,
       l.audience_count as audienceCount, l.reservation_count as reservationCount,
       if(r.reservation_id is null or r.status = '1', 0, 1) as reserved,
       if(f.favorite_id is null or f.status = '1', 0, 1) as favorite,
       p.progress_percent as progress
from dh_live_session l
left join dh_live_creator c on c.creator_id = l.creator_id
left join dh_live_topic t on t.topic_id = l.topic_id
left join dh_live_reservation r on r.live_id = l.live_id and r.member_id = #{memberId}
left join dh_live_member_favorite f on f.target_type = 'live' and f.target_id = l.live_id and f.member_id = #{memberId}
left join dh_live_learning_progress p on p.target_type = 'live' and p.target_id = l.live_id and p.member_id = #{memberId}
where l.publish_status = '1'
  and l.del_flag = '0'

  and l.status = #{status}

order by l.status asc, l.start_time asc, l.sort asc

select l.live_id as id, l.biz_code as bizCode, l.course_id as courseId,
       l.topic_id as topicId, t.topic_name as topic, l.creator_id as creatorId,
       c.creator_name as teacher, c.avatar as teacherAvatar, c.title as teacherTitle,
       l.title, l.subtitle, l.description, l.cover_image as coverImage,
       l.start_time as startTime, l.end_time as endTime, l.status as statusCode,
       l.h5_url as h5Url, l.replay_url as replayUrl, l.duration_seconds as durationSeconds,
       l.audience_count as audienceCount, l.reservation_count as reservationCount,
       if(r.reservation_id is null or r.status = '1', 0, 1) as reserved,
       if(f.favorite_id is null or f.status = '1', 0, 1) as favorite,
       p.progress_percent as progress,
       p.last_position_seconds as lastPositionSeconds
from dh_live_session l
left join dh_live_creator c on c.creator_id = l.creator_id
left join dh_live_topic t on t.topic_id = l.topic_id
left join dh_live_reservation r on r.live_id = l.live_id and r.member_id = #{memberId}
left join dh_live_member_favorite f on f.target_type = 'live' and f.target_id = l.live_id and f.member_id = #{memberId}
left join dh_live_learning_progress p on p.target_type = 'live' and p.target_id = l.live_id and p.member_id = #{memberId}
where l.biz_code = #{bizCode}
  and l.del_flag = '0'
limit 1

select c.content_id as id, c.biz_code as bizCode, c.topic_id as topicId, t.topic_code as topicCode, t.topic_name as topic, c.creator_id as creatorId, cr.creator_name as creator, c.content_kind as kind, c.title, c.summary, c.cover_image as coverImage, c.video_url as videoUrl, c.duration_seconds as durationSeconds, c.read_time_minutes as readTimeMinutes, c.likes_count as likesCount, c.favorites_count as favoritesCount, c.comments_count as commentsCount, if(f.favorite_id is null or f.status = '1', 0, 1) as favorite, if(l.like_id is null or l.status = '1', 0, 1) as liked from dh_live_content c left join dh_live_topic t on t.topic_id = c.topic_id left join dh_live_creator cr on cr.creator_id = c.creator_id left join dh_live_member_favorite f on f.target_type = 'content' and f.target_id = c.content_id and f.member_id = #{memberId} left join dh_live_member_like l on l.target_type = 'content' and l.target_id = c.content_id and l.member_id = #{memberId} where c.publish_status = '1' and c.del_flag = '0'
and t.topic_code = #{topicCode}
and c.content_kind = #{kind}
and c.title like concat('%', #{keyword}, '%')
order by c.sort asc, c.publish_time desc, c.content_id desc

select progress_id as id, member_id as memberId, target_type as targetType, target_id as targetId, progress_percent as progressPercent, study_seconds as studySeconds, last_position_seconds as lastPositionSeconds, last_study_time as lastStudyTime, completed_time as completedTime, status, remark from dh_live_learning_progress where member_id = #{memberId}
and target_type = #{targetType}
order by last_study_time desc, progress_id desc
